#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Sets up one NAISEMA v1 environment on Cloudflare (ADR-0015; docs/handover/runbook.md,
# "One-time provisioning"). Run from anywhere in the repository:
#
#   bash scripts/setup-environment.sh staging
#   bash scripts/setup-environment.sh production
#
# The values you type that aren't keys or tokens are remembered in .wizard-<env>.env
# (git-ignored), so a re-run offers them again. Keys and tokens go straight to Cloudflare and
# GitHub and are never written to disk, apart from a private temporary file for the first deploy.

TARGET="${1:-}"
if [[ "$TARGET" != "staging" && "$TARGET" != "production" ]]; then
  printf 'Usage: bash scripts/setup-environment.sh <staging|production>\n' >&2
  exit 1
fi
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=".wizard-${TARGET}.env"
REPO="naisema-fj/naisema"
CONFIG="wrangler.jsonc"

if [[ "$TARGET" == "staging" ]]; then
  WORKER="naisema-staging"; DATABASE="naisema-v1-staging"; BUCKET="naisema-staging-media"
  PUBLIC_HOST="staging.naisema.com"; ADMIN_HOST="admin.staging.naisema.com"
  OLD_QUEUE="naisema-staging-upload-scans"
  DB_PLACEHOLDER="REPLACE_WITH_STAGING_DATABASE_ID"
else
  WORKER="naisema-production"; DATABASE="naisema-v1-production"; BUCKET="naisema-production-media"
  PUBLIC_HOST="naisema.com"; ADMIN_HOST="admin.naisema.com"
  OLD_QUEUE="naisema-production-upload-scans"
  DB_PLACEHOLDER="REPLACE_WITH_PRODUCTION_DATABASE_ID"
fi
ACCOUNT_ID=$(grep -Eo '"account_id": *"[0-9a-f]{32}"' "$CONFIG" | grep -Eo '[0-9a-f]{32}' | head -n1)

# Secrets for the first deploy, in a file only this user can read, deleted on exit.
SECRETS_FILE=$(mktemp)
chmod 600 "$SECRETS_FILE"
trap 'rm -f "$SECRETS_FILE"' EXIT
add_deploy_secret() { printf '%s=%s\n' "$1" "$2" >> "$SECRETS_FILE"; }

wrangler() { pnpm --silent wrangler "$@"; }

# config_has TEXT: whether wrangler.jsonc still contains TEXT (a placeholder not yet filled in).
config_has() { grep -q "$1" "$CONFIG"; }

# fill_config PLACEHOLDER VALUE: puts VALUE where PLACEHOLDER is in wrangler.jsonc.
fill_config() {
  if config_has "$1"; then
    local escaped; escaped=$(printf '%s' "$2" | sed 's/[&|\\]/\\&/g')
    sed -i.bak "s|$1|$escaped|g" "$CONFIG" && rm -f "$CONFIG.bak"
    printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$2" "$CONFIG"
  else
    note "$CONFIG already has this value; leaving it as it is."
  fi
}

# set_env_secret NAME VALUE: a secret on the GitHub environment (not the whole repository).
set_env_secret() {
  if printf '%s' "$2" | gh secret set "$1" --env "$TARGET" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1 ($TARGET environment)")
    printf '  %s✓ set%s GitHub %s environment secret %s\n' "$GREEN" "$RESET" "$TARGET" "$1"
  else
    SKIPPED+=("GitHub secret $1 on the $TARGET environment (gh secret set $1 --env $TARGET --repo $REPO)")
    warn "couldn't set $1 on GitHub; set it later"
  fi
}

# ask_until KEY "Prompt" REGEX "what it should look like": asks again until the answer matches.
ask_until() {
  while true; do
    ask "$1" "$2"
    [[ "${!1}" =~ $3 ]] && return
    warn "That doesn't look right: it should be $4."
  done
}

TOTAL_STAGES=10

banner "NAISEMA v1: set up $TARGET"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and sign-in"
say "First, the tools this needs, and signing in to Cloudflare and GitHub."
for tool in git node pnpm gh openssl curl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool isn't installed. Install it, then run this wizard again."
    exit 1
  fi
done
step "Installing the project's packages..."
pnpm install --frozen-lockfile >/dev/null
signed_in() { local who; who=$(wrangler whoami 2>/dev/null || true); [[ "$who" == *"$ACCOUNT_ID"* ]]; }
if ! signed_in; then
  step "A browser opens to sign Wrangler in to Cloudflare. Sign in with the account that owns NAISEMA."
  wrangler login
fi
if ! signed_in; then
  warn "Wrangler is signed in, but can't see the NAISEMA account ($ACCOUNT_ID)."
  warn "Sign in as someone with admin access to it, then run this wizard again."
  exit 1
fi
printf '  %s✓%s Cloudflare: NAISEMA account %s\n' "$GREEN" "$RESET" "$ACCOUNT_ID"
if ! gh auth status >/dev/null 2>&1; then
  step "Now GitHub: follow the prompts to sign in."
  gh auth login
fi
printf '  %s✓%s GitHub: signed in\n' "$GREEN" "$RESET"
note "naisema.com must be an active zone in this Cloudflare account, for $PUBLIC_HOST and $ADMIN_HOST."
pause "Press Enter for the next stage."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Retire the Phase 1a Worker"
if [[ "$(_existing RETIRED_PHASE1A || true)" == "yes" ]]; then
  note "Done on an earlier run: nothing to do."
elif ! wrangler deployments list --name "$WORKER" >/dev/null 2>&1; then
  note "There is no $WORKER Worker yet, so nothing old is in the way."
  write_env RETIRED_PHASE1A yes
else
  say "A Worker called $WORKER already exists. If it is the Phase 1a one, it ran the ClamAV"
  say "scanner and an upload queue, and v1 can't simply replace it: it has to be deleted first."
  say "Phase 1a $TARGET held no real data. Its old database and buckets are kept; only the Worker goes."
  warn "Answer no if $WORKER is already running v1 (set up by this wizard on another computer)."
  if confirm "Delete the Phase 1a $WORKER Worker and its upload queue?"; then
    wrangler queues consumer remove "$OLD_QUEUE" "$WORKER" 2>/dev/null || note "No queue consumer to remove."
    step "Wrangler asks you to confirm the delete:"
    wrangler delete --name "$WORKER"
    wrangler queues delete "$OLD_QUEUE" 2>/dev/null || note "No upload queue to delete."
    note "If the Containers page still lists a scanner application, delete it there too:"
    note "  pnpm wrangler containers list, then pnpm wrangler containers delete <ID>"
    write_env RETIRED_PHASE1A yes
  else
    note "Left as it is."
    write_env RETIRED_PHASE1A yes
  fi
fi
pause "Press Enter for the next stage."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Database"
if config_has "$DB_PLACEHOLDER"; then
  say "Creating a fresh D1 database, $DATABASE, in Oceania. v1 starts again at migration 0000,"
  say "so it never reuses a Phase 1a database."
  wrangler d1 create "$DATABASE" --location oc --update-config=false || note "It may exist already; looking it up."
  DATABASE_ID=$(wrangler d1 list --json | node -e '
    let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => {
      const db = JSON.parse(s).find((row) => row.name === process.argv[1]);
      process.stdout.write(db ? db.uuid : "");
    });' "$DATABASE")
  if [[ -z "$DATABASE_ID" ]]; then
    warn "Couldn't find $DATABASE. Check the D1 page in the dashboard, then run this wizard again."
    exit 1
  fi
  write_env DATABASE_ID "$DATABASE_ID"
  fill_config "$DB_PLACEHOLDER" "$DATABASE_ID"
else
  note "$CONFIG already names the $TARGET database: nothing to do."
fi
pause "Press Enter for the next stage."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Media bucket"
if wrangler r2 bucket info "$BUCKET" >/dev/null 2>&1; then
  note "$BUCKET already exists: nothing to do. It stays private; the Worker serves its files itself."
else
  say "Creating the private R2 bucket $BUCKET, in Oceania."
  wrangler r2 bucket create "$BUCKET" --location oc --update-config=false
fi
pause "Press Enter for the next stage."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Bot check on the forms: Turnstile"
if [[ "$TARGET" == "staging" ]]; then
  say "Staging uses Cloudflare's Turnstile test keys, which always pass, so there is no widget to make."
  say "The test site key is already in $CONFIG; the matching test secret goes on the Worker."
  add_deploy_secret TURNSTILE_SECRET_KEY "1x0000000000000000000000000000000AA"
  printf '  %s✓%s test secret ready for the deploy\n' "$GREEN" "$RESET"
else
  open_url "https://dash.cloudflare.com/$ACCOUNT_ID/turnstile"
  step "Add widget. Name: NAISEMA production. Hostname: $PUBLIC_HOST. Widget mode: Managed."
  step "Create it, then copy the Site Key and the Secret Key."
  ask_until TURNSTILE_SITE_KEY "Paste the Site Key:" '^0x[0-9A-Za-z_-]+$' "a key starting 0x"
  ask_secret TURNSTILE_SECRET "Paste the Secret Key:"
  write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
  fill_config "REPLACE_WITH_TURNSTILE_SITE_KEY" "$TURNSTILE_SITE_KEY"
  add_deploy_secret TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET"
fi
pause "Press Enter for the next stage."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Preview links and form notifications"
existing_secrets=$(wrangler secret list --name "$WORKER" 2>/dev/null || true)
if [[ "$existing_secrets" == *'"PREVIEW_SECRET"'* ]] \
  && ! confirm "The Worker already has PREVIEW_SECRET. Replace it? (That ends every preview link already sent.)"; then
  note "Keeping the existing PREVIEW_SECRET."
else
  add_deploy_secret PREVIEW_SECRET "$(openssl rand -base64 32)"
  printf '  %s✓%s made a new random PREVIEW_SECRET, which signs preview links\n' "$GREEN" "$RESET"
fi
say "Who should be emailed when someone sends an enquiry or an offer through the site?"
note "Reports go to the Safeguarding Lead and privacy requests to administrators, from the staff list."
ask_until NOTIFY_EMAILS "Their addresses, comma-separated:" '^[^@ ,]+@[^@ ,]+(, *[^@ ,]+@[^@ ,]+)*$' "addresses like a@example.org, b@example.org"
write_env NOTIFY_EMAILS "$NOTIFY_EMAILS"
add_deploy_secret NOTIFY_EMAILS "$NOTIFY_EMAILS"
pause "Press Enter for the next stage."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Sending email from no-reply@naisema.com"
say "Staff sign-in links and form notifications are sent through Cloudflare Email Service,"
say "from no-reply@naisema.com. Without it, nobody can sign in to the staff site."
if [[ "$(_existing EMAIL_DOMAIN_READY || true)" == "yes" ]]; then
  note "Done on an earlier run: nothing to do."
else
  open_url "https://dash.cloudflare.com/$ACCOUNT_ID"
  step "Compute → Email Service → Email Sending → Onboard Domain, and choose naisema.com."
  step "Accept the SPF, DKIM, DMARC and bounce records Cloudflare proposes."
  warn "If any @naisema.com address already receives mail, check the MX records it proposes first."
  note "Done this already for the other environment? It's the same domain, so skip it."
  pause "Press Enter once naisema.com shows as a sending domain."
  write_env EMAIL_DOMAIN_READY yes
fi
pause "Press Enter for the next stage."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: deploys from CI"
say "From now on GitHub deploys $TARGET itself. It needs the account ID, a $TARGET environment,"
say "and a Cloudflare API token that only that environment can read."
set_var CLOUDFLARE_ACCOUNT_ID "$ACCOUNT_ID"
if gh api -X PUT "repos/$REPO/environments/$TARGET" >/dev/null 2>&1; then
  printf '  %s✓%s GitHub environment %s exists\n' "$GREEN" "$RESET" "$TARGET"
else
  SKIPPED+=("GitHub environment $TARGET (Settings → Environments → New environment)")
  warn "couldn't create the $TARGET environment on GitHub"
fi
if [[ "$TARGET" == "production" ]]; then
  open_url "https://github.com/$REPO/settings/environments"
  step "Open production → Required reviewers: add who must approve each production deploy."
  pause "Press Enter once a reviewer is set."
fi
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token. Name it: NAISEMA $TARGET deploys."
step "Permissions (Account): Workers Scripts Edit, D1 Edit, Workers R2 Storage Edit,"
step "  Cloudflare Images Edit, Account Settings Read."
step "Permissions (Zone): Workers Routes Edit, DNS Edit."
step "Account resources: the NAISEMA account. Zone resources: naisema.com."
step "Continue to summary → Create Token, then copy the token. It's shown only once."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token:"
if [[ -n "$CLOUDFLARE_API_TOKEN" ]]; then
  set_env_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
else
  SKIPPED+=("CLOUDFLARE_API_TOKEN on the $TARGET GitHub environment")
fi
unset CLOUDFLARE_API_TOKEN
pause "Press Enter for the next stage."

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Database tables, first administrator and first deploy"
step "Creating the tables in $DATABASE..."
wrangler d1 migrations apply DB --remote --env "$TARGET" --config "$CONFIG"
say "Who is the first administrator? They add everyone else at /admin/staff later."
ask_until ADMIN_EMAIL "Their email address:" '^[^@ ]+@[^@ ]+\.[^@ ]+$' "an address like name@example.org"
ask ADMIN_NAME "Their name:"
write_env ADMIN_EMAIL "$ADMIN_EMAIL"
write_env ADMIN_NAME "$ADMIN_NAME"
node scripts/grant-staff.mjs "$TARGET" "$ADMIN_EMAIL" "$ADMIN_NAME" admin,editor
note "They sign in at https://$ADMIN_HOST/admin/sign-in with that address, and get a link by email."
if confirm "Build and deploy $TARGET now, from this computer?"; then
  CLOUDFLARE_ENV="$TARGET" pnpm build >/dev/null
  wrangler deploy --secrets-file "$SECRETS_FILE"
  step "Checking https://$PUBLIC_HOST/health (a new domain's certificate can take a few minutes)..."
  healthy=""
  for _ in $(seq 1 20); do
    if [[ "$(curl -fsS "https://$PUBLIC_HOST/health" 2>/dev/null || true)" == "ok" ]]; then healthy=yes; break; fi
    sleep 15
  done
  if [[ -n "$healthy" ]]; then
    printf '  %s✓%s https://%s/health answers ok\n' "$GREEN" "$RESET" "$PUBLIC_HOST"
  else
    SKIPPED+=("https://$PUBLIC_HOST/health didn't answer ok yet; try it again in a few minutes")
    warn "/health didn't answer ok yet. Try it again in a few minutes."
  fi
  location=$(curl -sS -o /dev/null -w '%{redirect_url}' "https://$ADMIN_HOST/admin/items" || true)
  if [[ "$location" == *"/admin/sign-in"* ]]; then
    printf '  %s✓%s %s asks visitors to sign in\n' "$GREEN" "$RESET" "$ADMIN_HOST"
  else
    SKIPPED+=("Check that https://$ADMIN_HOST/admin/items asks you to sign in")
    warn "$ADMIN_HOST didn't send us to its sign-in page. Check the deploy above."
  fi
  say "Now sign in: open https://$ADMIN_HOST/admin/sign-in and ask for a link for $ADMIN_EMAIL."
else
  SKIPPED+=("First deploy: merge the wrangler.jsonc pull request (stage 11), then set the secrets with pnpm wrangler secret put")
fi
pause "Press Enter for the last stage."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Save the settings in the repository"
say "$CONFIG now holds $TARGET's database ID. It isn't secret."
say "They go in through a pull request, so every later deploy from GitHub uses them."
git --no-pager diff --stat -- "$CONFIG"
if git diff --quiet -- "$CONFIG"; then
  note "Nothing changed in $CONFIG: nothing to commit."
elif confirm "Open a pull request with these $CONFIG changes?"; then
  branch="setup/$TARGET-$(date +%Y%m%d)"
  git switch -c "$branch"
  git add "$CONFIG"
  git commit -m "Set the $TARGET database in wrangler.jsonc (scripts/setup-environment.sh)"
  git push -u origin "$branch"
  gh pr create --repo "$REPO" --fill --base main
else
  SKIPPED+=("Commit the $CONFIG changes in a pull request")
fi

finish
say "Next: docs/launch-checklist.md, from where this leaves off."
